            xs = [x for y, x in cells]
            r0, r1, c0, c1 = min(ys), max(ys), min(xs), max(xs)
            counts = Counter(grid[y][x] for y, x in cells)
            frame = counts.most_common(1)[0][0]
            interior = [(y, x) for y, x in cells if grid[y][x] != frame]
            if not interior:
                continue
            color = Counter(grid[y][x] for y, x in interior).most_common(1)[0][0]
            iy = [y for y, x in interior if grid[y][x] == color]
            ix = [x for y, x in interior if grid[y][x] == color]
            tiles.append(dict(r0=r0, r1=r1, c0=c0, c1=c1, color=color,
