    out = [row[:] for row in grid]
    row_groups, col_groups = {}, {}
    for tile in tiles:
        row_groups.setdefault((tile['r0'], tile['r1']), []).append(tile)
        col_groups.setdefault((tile['c0'], tile['c1']), []).append(tile)

    # Connect a color only when it occurs exactly twice in that tile row or column.
    for group in row_groups.values():
        counts = Counter(tile['color'] for tile in group)
        for color, count in counts.items():
            if count != 2:
                continue
            a, b = sorted((t for t in group if t['color'] == color), key=lambda t: t['c0'])
            for y in range(max(a['y0'], b['y0']), min(a['y1'], b['y1']) + 1):
                for x in range(a['c1'] + 1, b['c0']):
                    if out[y][x] == 0:
